'use strict';
const shareDialog=document.createElement('dialog');shareDialog.className='share-dialog';shareDialog.innerHTML='<button class="share-close" aria-label="关闭">×</button><h2>分享这一盘</h2><div class="share-preview"><canvas id="shareCanvas" width="1080" height="1440"></canvas></div><div class="share-actions"><button id="downloadCard">下载图片</button><button id="copyReading" class="secondary">复制解卦文案</button><button id="systemShare" class="secondary">系统分享</button></div><p class="share-toast" id="shareToast"></p>';document.body.append(shareDialog);
const shareCanvas=document.getElementById('shareCanvas'),shareCtx=shareCanvas.getContext('2d');let sharePayload=null;
function cardRoundRect(ctx,x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.stroke()}}
function cardWrap(ctx,text,x,y,maxWidth,lineHeight,maxLines=99){const chars=[...String(text)],lines=[];let line='';for(const ch of chars){const test=line+ch;if(ctx.measureText(test).width>maxWidth&&line){lines.push(line);line=ch}else line=test}if(line)lines.push(line);const shown=lines.slice(0,maxLines);if(lines.length>maxLines)shown[maxLines-1]=shown[maxLines-1].slice(0,-1)+'…';shown.forEach((s,i)=>ctx.fillText(s,x,y+i*lineHeight));return y+shown.length*lineHeight}
function buildSharePayload(){if(!lastRenderContext)return null;const {record,p}=lastRenderContext,palace=PALACES[p.t][0],full=record.question+(record.details?' '+record.details:'');if(record.category==='lost'){const r=getLostReading(p,full);return{record,p,palace,type:CATEGORIES.lost[0],verdict:r.chance,focus:`${r.direction}｜${r.position}`,closing:`此课寻物落${palace}，${r.chance}。先按所示方位和位置有序查找，现实中的定位、挂失与失物招领也应同步进行。`,action:r.actions[0]}}const r=getTopicReading(p,record.category,full);return{record,p,palace,type:CATEGORIES[record.category][0],verdict:r.verdict,focus:r.focus,closing:r.closing,action:r.actions[0]}}
function drawShareCard(data){const c=shareCtx,w=1080,h=1440;c.clearRect(0,0,w,h);const bg=c.createLinearGradient(0,0,w,h);bg.addColorStop(0,'#fffaf0');bg.addColorStop(.56,'#f7ecd8');bg.addColorStop(1,'#eee0c8');c.fillStyle=bg;c.fillRect(0,0,w,h);c.strokeStyle='rgba(142,81,49,.10)';c.lineWidth=2;for(let i=-h;i<w;i+=70){c.beginPath();c.moveTo(i,0);c.lineTo(i+h,h);c.stroke()}c.fillStyle='rgba(182,70,50,.055)';c.beginPath();c.arc(970,145,245,0,Math.PI*2);c.fill();c.strokeStyle='rgba(182,70,50,.16)';c.lineWidth=2;[115,165,215].forEach(r=>{c.beginPath();c.arc(970,145,r,0,Math.PI*2);c.stroke()});cardRoundRect(c,62,62,956,1316,34,'rgba(255,253,247,.92)','rgba(131,85,49,.20)');c.fillStyle='#b64632';c.font='700 38px "Microsoft YaHei"';c.fillText('問 時',105,135);c.fillStyle='#7d6a57';c.font='24px "Microsoft YaHei"';c.fillText('小六壬 · 一问一盘',105,179);c.textAlign='center';c.fillStyle='#b64632';c.font='700 126px "STSong","SimSun",serif';c.fillText(data.palace,540,350);c.fillStyle='#315c50';c.font='700 26px "Microsoft YaHei"';c.fillText(`${data.type} · ${PALACES[data.p.d][0]}＋${data.palace}`,540,402);c.textAlign='left';c.fillStyle='#92785e';c.font='700 22px "Microsoft YaHei"';c.fillText('所 问',108,488);c.fillStyle='#302c27';c.font='700 38px "Microsoft YaHei"';let y=cardWrap(c,data.record.question,108,545,864,57,3)+24;cardRoundRect(c,100,y,880,152,22,'#224e43');c.fillStyle='#e9cf95';c.font='700 20px "Microsoft YaHei"';c.fillText('直接判断',135,y+43);c.fillStyle='#fffaf0';c.font='700 31px "Microsoft YaHei"';cardWrap(c,data.verdict,135,y+91,810,43,2);y+=195;c.fillStyle='#92785e';c.font='700 21px "Microsoft YaHei"';c.fillText('关键所在',108,y);c.fillStyle='#4a4036';c.font='28px "Microsoft YaHei"';y=cardWrap(c,data.focus,108,y+48,864,43,3)+30;c.strokeStyle='rgba(142,81,49,.20)';c.beginPath();c.moveTo(108,y);c.lineTo(972,y);c.stroke();y+=57;c.fillStyle='#b64632';c.font='700 22px "Microsoft YaHei"';c.fillText('解 卦 语',108,y);c.fillStyle='#41372f';c.font='29px "STSong","SimSun",serif';y=cardWrap(c,data.closing,108,y+56,864,48,7)+35;cardRoundRect(c,100,1190,880,92,18,'rgba(181,139,70,.11)','rgba(160,115,59,.18)');c.fillStyle='#5f503f';c.font='24px "Microsoft YaHei"';cardWrap(c,'此刻行动：'+data.action,130,1238,820,34,2);c.fillStyle='#8d7865';c.font='20px "Microsoft YaHei"';c.fillText('传统民俗体验 · 结果仅作思考参考',108,1330);c.textAlign='right';c.fillStyle='#315c50';c.font='700 21px "Microsoft YaHei"';c.fillText('问时 · 小六壬',972,1330);c.textAlign='left'}
function shareText(data){return `【问时 · 小六壬】\n所问：${data.record.question}\n落宫：${data.palace}（${PALACES[data.p.d][0]}＋${data.palace}）\n判断：${data.verdict}\n解卦：${data.closing}\n\n传统民俗体验，仅作思考参考。`}
function canvasBlob(){return new Promise(resolve=>shareCanvas.toBlob(resolve,'image/png',.96))}
function attachShareToolbar(){const result=document.getElementById('result');if(result.hidden||result.querySelector('.share-toolbar')||!lastRenderContext)return;const anchor=result.querySelector('.closing-reading')||result.querySelector('.trace');if(!anchor)return;const bar=document.createElement('div');bar.className='share-toolbar';bar.innerHTML='<span>把这一盘保存下来，或分享给需要的人</span><button type="button">生成分享卡片 ↗</button>';bar.querySelector('button').addEventListener('click',()=>{sharePayload=buildSharePayload();if(!sharePayload)return;drawShareCard(sharePayload);document.getElementById('shareToast').textContent='';shareDialog.showModal()});anchor.insertAdjacentElement('afterend',bar)}
new MutationObserver(attachShareToolbar).observe(document.getElementById('result'),{childList:true,subtree:true});
shareDialog.querySelector('.share-close').addEventListener('click',()=>shareDialog.close());shareDialog.addEventListener('click',e=>{if(e.target===shareDialog)shareDialog.close()});
document.getElementById('downloadCard').addEventListener('click',async()=>{const blob=await canvasBlob(),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`问时-${sharePayload.palace}-${Date.now()}.png`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);document.getElementById('shareToast').textContent='分享卡片已下载。'});
document.getElementById('copyReading').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(shareText(sharePayload));document.getElementById('shareToast').textContent='解卦文案已复制。'}catch{document.getElementById('shareToast').textContent='复制失败，请使用系统分享。'}});
document.getElementById('systemShare').addEventListener('click',async()=>{const blob=await canvasBlob(),file=new File([blob],`问时-${sharePayload.palace}.png`,{type:'image/png'});try{if(navigator.canShare?.({files:[file]}))await navigator.share({title:'问时 · 小六壬',text:shareText(sharePayload),files:[file]});else if(navigator.share)await navigator.share({title:'问时 · 小六壬',text:shareText(sharePayload)});else throw new Error();}catch(e){if(e.name!=='AbortError')document.getElementById('shareToast').textContent='当前浏览器不支持系统分享，请下载图片或复制文案。'}});
